contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    uint public cBefore;
    uint public thisBefore;
    uint public cAfter;
    uint public thisAfter;
    bool public reverted;

    function run(uint v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(c).balance >= v);

        cBefore = address(c).balance;
        thisBefore = address(this).balance;

        reverted = false;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        cAfter = address(c).balance;
        thisAfter = address(this).balance;

        assert(reverted ? (cAfter == cBefore && thisAfter == thisBefore) : (cAfter == cBefore - v));
    }

    receive() external payable {}
}

