// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    uint public cBefore;
    uint public thisBefore;
    uint public cAfter;
    uint public thisAfter;
    bool public reverted;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(c).balance >= v);
        cBefore = address(c).balance;
        thisBefore = address(this).balance;
        reverted = false;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        cAfter = address(c).balance;
        thisAfter = address(this).balance;
        assertTrue(reverted ? (cAfter == cBefore && thisAfter == thisBefore) : (cAfter == cBefore - v));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
